mapper.select:
WITH RECURSIVE requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ), matched_rows AS ( SELECT c.id, c.parent_id, c.path FROM product_category c INNER JOIN normalized_requested r ON r.id = c.id ), matched_child_counts AS ( SELECT child.parent_id, COUNT(*) AS child_count FROM product_category child WHERE child.parent_id IN (SELECT id FROM matched_rows) GROUP BY child.parent_id ), raw_anchors AS ( SELECT DISTINCT CASE WHEN COALESCE(mcc.child_count, 0) > 0 THEN mr.id WHEN mr.parent_id > 0 THEN mr.parent_id ELSE mr.id END AS id FROM matched_rows mr LEFT JOIN matched_child_counts mcc ON mcc.parent_id = mr.id ), anchor_rows AS ( SELECT DISTINCT c.id, c.parent_id, c.path FROM product_category c INNER JOIN raw_anchors a ON a.id = c.id ), final_anchors AS ( SELECT a.id, a.parent_id, a.path FROM anchor_rows a WHERE NOT EXISTS ( SELECT 1 FROM anchor_rows parent WHERE parent.id <> a.id AND a.path LIKE parent.path || '%' ) ), descendants(id) AS ( SELECT id FROM final_anchors UNION SELECT child.id FROM product_category child INNER JOIN descendants d ON d.id = child.parent_id ), ancestors(id, parent_id) AS ( SELECT id, parent_id FROM final_anchors UNION SELECT parent.id, parent.parent_id FROM product_category parent INNER JOIN ancestors child ON child.parent_id = parent.id ), display_ids AS ( SELECT id FROM descendants UNION SELECT id FROM ancestors ), child_counts AS ( SELECT parent_id, COUNT(*) AS child_count FROM product_category GROUP BY parent_id ), product_counts AS ( SELECT category_id, COUNT(*) AS product_count, COUNT(*) FILTER (WHERE status = 'ACTIVE') AS active_product_count FROM product_spu GROUP BY category_id ) SELECT DISTINCT c.id AS "id", c.parent_id AS "parentId", c.name AS "name", c.code AS "code", c.level AS "level", c.path AS "path", c.sort_order AS "sortOrder", COALESCE(c.icon_urls, '[]'::jsonb)::text AS "iconUrlsJson", c.description AS "description", c.status AS "status", c.is_leaf AS "isLeaf", COALESCE(cc.child_count, 0) AS "childCount", COALESCE(pc.product_count, 0) AS "productCount", COALESCE(pc.active_product_count, 0) AS "activeProductCount", c.created_at AS "createdAt", c.updated_at AS "updatedAt" FROM product_category c INNER JOIN display_ids d ON d.id = c.id LEFT JOIN child_counts cc ON cc.parent_id = c.id LEFT JOIN product_counts pc ON pc.category_id = c.id ORDER BY c.level ASC, c.parent_id ASC, c.sort_order ASC, c.id ASC

WITH RECURSIVE requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ), matched_rows AS ( SELECT c.id, c.parent_id, c.path FROM product_category c INNER JOIN normalized_requested r ON r.id = c.id WHERE c.status = 'ACTIVE' ), matched_child_counts AS ( SELECT child.parent_id, COUNT(*) AS child_count FROM product_category child WHERE child.status = 'ACTIVE' AND child.parent_id IN (SELECT id FROM matched_rows) GROUP BY child.parent_id ), raw_anchors AS ( SELECT DISTINCT CASE WHEN COALESCE(mcc.child_count, 0) > 0 THEN mr.id WHEN mr.parent_id > 0 THEN mr.parent_id ELSE mr.id END AS id FROM matched_rows mr LEFT JOIN matched_child_counts mcc ON mcc.parent_id = mr.id ), anchor_rows AS ( SELECT DISTINCT c.id, c.parent_id, c.path FROM product_category c INNER JOIN raw_anchors a ON a.id = c.id WHERE c.status = 'ACTIVE' ), final_anchors AS ( SELECT a.id, a.parent_id, a.path FROM anchor_rows a WHERE NOT EXISTS ( SELECT 1 FROM anchor_rows parent WHERE parent.id <> a.id AND a.path LIKE parent.path || '%' ) ), descendants(id) AS ( SELECT id FROM final_anchors UNION SELECT child.id FROM product_category child INNER JOIN descendants d ON d.id = child.parent_id WHERE child.status = 'ACTIVE' ), ancestors(id, parent_id) AS ( SELECT id, parent_id FROM final_anchors UNION SELECT parent.id, parent.parent_id FROM product_category parent INNER JOIN ancestors child ON child.parent_id = parent.id WHERE parent.status = 'ACTIVE' ), display_ids AS ( SELECT id FROM descendants UNION SELECT id FROM ancestors ) SELECT DISTINCT c.id AS "id", c.parent_id AS "parentId", c.name AS "name", c.code AS "code", c.level AS "level", c.sort_order AS "sortOrder", COALESCE(c.icon_urls, '[]'::jsonb)::text AS "iconUrlsJson", c.status AS "status" FROM product_category c INNER JOIN display_ids d ON d.id = c.id WHERE c.status = 'ACTIVE' ORDER BY c.level ASC, c.parent_id ASC, c.sort_order ASC, c.id ASC

WITH requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ) SELECT c.id AS "id", c.parent_id AS "parentId", c.name AS "name", c.code AS "code", c.level AS "level", c.path AS "path", c.sort_order AS "sortOrder", COALESCE(c.icon_urls, '[]'::jsonb)::text AS "iconUrlsJson", c.description AS "description", c.status AS "status", c.is_leaf AS "isLeaf", c.created_at AS "createdAt", c.updated_at AS "updatedAt" FROM product_category c INNER JOIN normalized_requested r ON r.id = c.id ORDER BY c.id ASC

WITH requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ), target_roots AS ( SELECT c.id, c.path FROM product_category c INNER JOIN normalized_requested r ON r.id = c.id ), target_tree AS ( SELECT DISTINCT c.id FROM product_category c INNER JOIN target_roots root ON c.path LIKE root.path || '%' ), active_products AS ( SELECT COUNT(*) AS active_product_count FROM product_spu p INNER JOIN target_tree t ON t.id = p.category_id WHERE p.status = 'ACTIVE' ), updated AS ( UPDATE product_category c SET status = 'DISABLED', updated_at = NOW() FROM target_tree t WHERE c.id = t.id AND c.status IS DISTINCT FROM 'DISABLED' AND (SELECT COUNT(*) FROM target_roots) = (SELECT COUNT(*) FROM normalized_requested) AND (SELECT active_product_count FROM active_products) = 0 RETURNING c.id ) SELECT (SELECT COUNT(*) FROM normalized_requested) AS "requestedCount", (SELECT COUNT(*) FROM target_roots) AS "rootCount", (SELECT COUNT(*) FROM target_tree) AS "subtreeCount", (SELECT active_product_count FROM active_products) AS "activeProductCount", (SELECT COUNT(*) FROM updated) AS "affectedCount", COALESCE((SELECT jsonb_agg(id ORDER BY id) FROM updated), '[]'::jsonb)::text AS "affectedIdsJson"
